const ALL_PLAYERS: readonly Player[] = [
  ...HOME_TEAM.lineup,
  HOME_TEAM.pitcher,
  HOME_TEAM.closer,
  ...AWAY_TEAM.lineup,
  AWAY_TEAM.pitcher,
  AWAY_TEAM.closer,
];

const BY_NAME = new Map<string, Player>(ALL_PLAYERS.map((p) => [p.name, p]));

export function findPlayer(name: string): Player | undefined {
  return BY_NAME.get(name);
}

export function batsHand(name: string): Hand {
  return findPlayer(name)?.bats ?? "R";
}

export function throwsHand(name: string): Hand {
  return findPlayer(name)?.throws ?? "R";
}

/** e.g. "R" / "L" / "S" for the matchup name line. */
export function formatBats(name: string): string {
  return batsHand(name);
}

/** e.g. "RHP" / "LHP". */
export function formatThrows(name: string): string {
  const t = throwsHand(name);
  return `${t === "S" ? "R" : t}HP`;
}

/** Spoken / screen-reader friendly. */
export function spokenHand(hand: Hand, role: "bats" | "throws"): string {
  if (hand === "S" && role === "bats") return "switch-hitter";
  const side = hand === "L" ? "left" : "right";
  return role === "bats" ? `${side}-handed batter` : `${side}-handed pitcher`;
}

/** Hand the batter uses this AB (switch resolved vs pitcher). */
export function batterHandForAb(batterName: string, pitcherName: string): BatterHand {
  return resolveBatterHand(batsHand(batterName), throwsHand(pitcherName));
}

export function formatBatterTeaser(name: string): string {
  const b = findPlayer(name)?.batter;
  if (!b) return "";
  return `CON ${b.contact} · PWR ${b.power}`;
}

export function formatPitcherTeaser(name: string): string {
  const p = findPlayer(name)?.pitcher;
  if (!p) return "";
  return `VEL ${p.velocity} · STF ${p.stuff}`;
}
