import type { AudioEngine } from "../AudioEngine.ts";
import { cancelFrom } from "../AudioEngine.ts";
import type { SampleVoice } from "../SampleBank.ts";
import { applyEnvelope } from "./shared.ts";

/**
 * CrowdBed — the stadium.
 *
 * With samples loaded: a real stadium loop is the bed (excitement drives its
 * gain); pink/white noise is muted. Without samples: the original synth murmur
 * / roar bed. Swells fire cheer / clap / roar one-shots on top.
 */

export type ExcitementLevel = 1 | 2 | 3 | 4 | 5;

interface LevelSpec {
  murmur: number;
  roar: number;
  brightness: number;
  sway: number;
  /** Stadium-loop level when samples are armed (replaces the noise bed). */
  sample: number;
}

const LEVELS: Record<ExcitementLevel, LevelSpec> = {
  // Half-empty on a Tuesday.
  1: { murmur: 0.34, roar: 0.0, brightness: 1200, sway: 0.16, sample: 0.55 },
  2: { murmur: 0.48, roar: 0.05, brightness: 1750, sway: 0.13, sample: 0.7 },
  // Something is happening.
  3: { murmur: 0.62, roar: 0.2, brightness: 2600, sway: 0.1, sample: 0.85 },
  4: { murmur: 0.78, roar: 0.48, brightness: 3700, sway: 0.07, sample: 0.95 },
  // Everyone on their feet. Barely any sway left — it's continuous.
  5: { murmur: 0.95, roar: 0.9, brightness: 5000, sway: 0.04, sample: 1.1 },
};

export class CrowdBed {
  private readonly engine: AudioEngine;
  private readonly murmurGain: GainNode;
  private readonly roarGain: GainNode;
  private readonly tone: BiquadFilterNode;
  private readonly swellGain: GainNode;
  private readonly sampleGain: GainNode;
  private readonly swayDepth: GainNode[] = [];
  private readonly sources: AudioScheduledSourceNode[] = [];
  private sampleBed: SampleVoice | null = null;

  private level: ExcitementLevel = 2;
  private running = false;
  private swellUntil = 0;
  private samplesArmed = false;

  constructor(engine: AudioEngine) {
    const { ctx } = engine;
    this.engine = engine;

    this.swellGain = ctx.createGain();
    this.swellGain.gain.value = 1;
    this.swellGain.connect(engine.busInput("crowd"));

    // Real stadium loop rides this node so excitement / swell automation applies.
    this.sampleGain = ctx.createGain();
    this.sampleGain.gain.value = 0;
    this.sampleGain.connect(this.swellGain);

    const sway = ctx.createGain();
    sway.gain.value = 1;
    sway.connect(this.swellGain);

    this.tone = ctx.createBiquadFilter();
    this.tone.type = "lowpass";
    this.tone.frequency.value = LEVELS[this.level].brightness;
    this.tone.Q.value = 0.5;
    this.tone.connect(sway);

    this.murmurGain = ctx.createGain();
    this.murmurGain.gain.value = LEVELS[this.level].murmur;
    this.murmurGain.connect(this.tone);

    this.roarGain = ctx.createGain();
    this.roarGain.gain.value = LEVELS[this.level].roar;
    this.roarGain.connect(this.tone);

    // Murmur: pink noise, band-limited to the range of massed human voices.
    for (const pan of [-0.85, 0.85]) {
      const source = engine.noise.source("pink", { loop: true });
      const band = ctx.createBiquadFilter();
      band.type = "bandpass";
      band.frequency.value = 420;
      band.Q.value = 0.45;
      const panner = ctx.createStereoPanner();
      panner.pan.value = pan;
      source.connect(band);
      band.connect(panner);
      panner.connect(this.murmurGain);
      this.sources.push(source);
    }

    // Roar: white noise, wider and brighter, sitting above the murmur.
    for (const pan of [-0.7, 0.7]) {
      const source = engine.noise.source("white", { loop: true, playbackRate: 0.85 });
      const band = ctx.createBiquadFilter();
      band.type = "bandpass";
      band.frequency.value = 1500;
      band.Q.value = 0.4;
      const panner = ctx.createStereoPanner();
      panner.pan.value = pan;
      source.connect(band);
      band.connect(panner);
      panner.connect(this.roarGain);
      this.sources.push(source);
    }

    // Two slow, mutually irrational LFOs summed into the sway gain.
    for (const rate of [0.11, 0.079]) {
      const lfo = ctx.createOscillator();
      lfo.type = "sine";
      lfo.frequency.value = rate;
      const depth = ctx.createGain();
      depth.gain.value = LEVELS[this.level].sway / 2;
      lfo.connect(depth);
      depth.connect(sway.gain);
      this.sources.push(lfo);
      this.swayDepth.push(depth);
    }
  }

  start(at?: number): void {
    if (this.running) return;
    this.running = true;
    const t = at ?? this.engine.ctx.currentTime;
    for (const source of this.sources) {
      if (source instanceof AudioBufferSourceNode) {
        source.start(t, this.engine.noise.randomOffset(1));
      } else {
        source.start(t);
      }
    }
    this.armSampleBed(t);
  }

  /** Call after SampleBank.load so the stadium loop can join a live bed. */
  attachSamples(at?: number): void {
    if (!this.running) return;
    this.armSampleBed(at ?? this.engine.ctx.currentTime);
  }

  private armSampleBed(at: number): void {
    if (this.samplesArmed || !this.engine.samples.has("crowd-bed")) return;

    const ctx = this.engine.ctx;
    const t = Math.max(at, ctx.currentTime);
    const spec = LEVELS[this.level];
    const buffer = this.engine.samples.get("crowd-bed");
    const offset = buffer ? Math.random() * Math.max(0, buffer.duration - 1) : 0;

    // Start the loop first; only mute the synth if playback actually begins.
    this.sampleGain.gain.cancelScheduledValues(t);
    this.sampleGain.gain.setValueAtTime(spec.sample, t);

    const voice = this.engine.samples.play(this.engine, "crowd-bed", {
      destination: this.sampleGain,
      at: t,
      gain: 1,
      loop: true,
      fadeIn: 0.35,
      offset,
    });
    if (!voice) {
      this.sampleGain.gain.setValueAtTime(0, t);
      return;
    }

    this.samplesArmed = true;
    this.sampleBed = voice;
    // Sample becomes the bed. Synth noise was reading as static on headphones.
    ramp(this.murmurGain.gain, 0, t, 0.45);
    ramp(this.roarGain.gain, 0, t, 0.45);
  }

  get excitement(): ExcitementLevel {
    return this.level;
  }

  setExcitement(level: ExcitementLevel, rampSeconds = 1.2, at?: number): void {
    this.level = level;
    const spec = LEVELS[level];
    const ctx = this.engine.ctx;
    const t = at ?? ctx.currentTime;

    // Don't stomp an in-flight swell; it will settle to the new base on release.
    if (t >= this.swellUntil) {
      if (this.samplesArmed) {
        ramp(this.sampleGain.gain, spec.sample, t, rampSeconds);
        ramp(this.murmurGain.gain, 0, t, rampSeconds);
        ramp(this.roarGain.gain, 0, t, rampSeconds);
      } else {
        ramp(this.murmurGain.gain, spec.murmur, t, rampSeconds);
        ramp(this.roarGain.gain, spec.roar, t, rampSeconds);
      }
    }
    ramp(this.tone.frequency, spec.brightness, t, rampSeconds);
    for (const depth of this.swayDepth) {
      ramp(depth.gain, spec.sway / 2, t, rampSeconds);
    }
  }

  /**
   * A reaction — a hit, a strikeout, a close play. Jumps to `peak`, holds, then
   * settles back to whatever the base excitement is by then.
   */
  swell(at: number, peak: ExcitementLevel, holdSeconds = 1.4): void {
    const ctx = this.engine.ctx;
    const t = Math.max(at, ctx.currentTime);
    const spec = LEVELS[peak];
    const attack = 0.12;
    const release = 1.8;
    const releaseStart = t + attack + holdSeconds;
    this.swellUntil = releaseStart + release;

    if (this.samplesArmed) {
      const base = LEVELS[this.level].sample;
      cancelFrom(this.sampleGain.gain, t);
      this.sampleGain.gain.linearRampToValueAtTime(spec.sample, t + attack);
      this.sampleGain.gain.setValueAtTime(spec.sample, releaseStart);
      this.sampleGain.gain.linearRampToValueAtTime(base, releaseStart + release);
    } else {
      for (const [param, target, base] of [
        [this.murmurGain.gain, spec.murmur, LEVELS[this.level].murmur],
        [this.roarGain.gain, spec.roar, LEVELS[this.level].roar],
        [this.tone.frequency, spec.brightness, LEVELS[this.level].brightness],
      ] as const) {
        cancelFrom(param, t);
        param.linearRampToValueAtTime(target, t + attack);
        param.setValueAtTime(target, releaseStart);
        param.linearRampToValueAtTime(base, releaseStart + release);
      }
    }

    cancelFrom(this.swellGain.gain, t);
    this.swellGain.gain.linearRampToValueAtTime(1.35, t + attack);
    this.swellGain.gain.setValueAtTime(1.35, releaseStart);
    this.swellGain.gain.linearRampToValueAtTime(1, releaseStart + release);

    this.playSwellOneShot(t, peak);
  }

  private playSwellOneShot(at: number, peak: ExcitementLevel): void {
    const { samples } = this.engine;
    if (peak >= 5 && samples.has("crowd-roar")) {
      samples.play(this.engine, "crowd-roar", {
        destination: this.swellGain,
        at,
        gain: 0.75,
        fadeIn: 0.05,
        fadeOut: 1.2,
        duration: 6.5,
      });
      return;
    }
    if (peak >= 4 && samples.has("crowd-cheer")) {
      samples.play(this.engine, "crowd-cheer", {
        destination: this.swellGain,
        at,
        gain: 0.65,
        fadeIn: 0.04,
        fadeOut: 0.8,
        duration: 4.2,
      });
      return;
    }
    if (peak >= 3 && samples.has("crowd-clap")) {
      samples.play(this.engine, "crowd-clap", {
        destination: this.swellGain,
        at,
        gain: 0.5,
        fadeIn: 0.02,
        fadeOut: 0.5,
        duration: 2.8,
      });
    }
  }

  /**
   * A vendor shout — "hot dogs", "beer here" — as a short formant bark from the
   * stands. Fires on the crowd bus so it sits under the booth rather than fighting
   * it, and is quiet enough that it reads as atmosphere, not as dialogue.
   */
  vendorCall(at: number, kind: "dogs" | "beer" | "programs" = "dogs"): void {
    const sampleId =
      kind === "beer" ? "vendor-beer" : kind === "dogs" ? "vendor-dogs" : "vendor-programs";
    if (this.engine.samples.has(sampleId)) {
      this.engine.samples.play(this.engine, sampleId, {
        bus: "crowd",
        at,
        gain: 0.42,
        pan: kind === "beer" ? 0.55 : kind === "programs" ? -0.45 : 0.15,
        fadeIn: 0.02,
        fadeOut: 0.4,
        duration: 3.2,
      });
      return;
    }

    const { ctx } = this.engine;
    const bus = this.engine.busInput("crowd");

    const pan = ctx.createStereoPanner();
    pan.pan.value = kind === "beer" ? 0.55 : kind === "programs" ? -0.45 : 0.15;
    pan.connect(bus);

    const grit = ctx.createWaveShaper();
    grit.curve = vendorRasp();
    grit.oversample = "2x";
    grit.connect(pan);

    const profile =
      kind === "beer"
        ? [
            { offset: 0, dur: 0.11, hz: 210, formant: 700, peak: 0.08 },
            { offset: 0.12, dur: 0.18, hz: 180, formant: 560, peak: 0.07 },
          ]
        : kind === "programs"
          ? [
              { offset: 0, dur: 0.1, hz: 240, formant: 780, peak: 0.07 },
              { offset: 0.11, dur: 0.14, hz: 200, formant: 620, peak: 0.06 },
              { offset: 0.26, dur: 0.16, hz: 170, formant: 540, peak: 0.06 },
            ]
          : [
              { offset: 0, dur: 0.09, hz: 230, formant: 760, peak: 0.08 },
              { offset: 0.1, dur: 0.2, hz: 190, formant: 600, peak: 0.08 },
            ];

    for (const syl of profile) {
      const voice = ctx.createOscillator();
      voice.type = "sawtooth";
      voice.frequency.setValueAtTime(syl.hz, at + syl.offset);
      voice.frequency.exponentialRampToValueAtTime(syl.hz * 0.85, at + syl.offset + syl.dur);

      const band = ctx.createBiquadFilter();
      band.type = "bandpass";
      band.frequency.value = syl.formant;
      band.Q.value = 3;

      const gain = ctx.createGain();
      voice.connect(band);
      band.connect(gain);
      gain.connect(grit);

      applyEnvelope(gain.gain, {
        at: at + syl.offset,
        attack: 0.015,
        hold: syl.dur * 0.35,
        decay: syl.dur * 0.5,
        peak: syl.peak,
        sustain: 0.7,
      });
      voice.start(at + syl.offset);
      voice.stop(at + syl.offset + syl.dur + 0.05);
    }
  }

  /** Between innings, or after something good. Unapologetically cheesy. */
  organStab(at: number, root = 261.63): void {
    const ctx = this.engine.ctx;
    const bus = this.engine.busInput("crowd");

    const shaper = ctx.createBiquadFilter();
    shaper.type = "lowpass";
    shaper.frequency.value = 2400;
    const out = ctx.createGain();
    shaper.connect(out);
    out.connect(bus);

    // Major triad plus the octave — a drawbar organ in four notes.
    for (const ratio of [1, 1.26, 1.5, 2]) {
      for (const detune of [-4, 4]) {
        const osc = ctx.createOscillator();
        osc.type = "square";
        osc.frequency.value = root * ratio;
        osc.detune.value = detune;
        const g = ctx.createGain();
        g.gain.value = 0.06;
        osc.connect(g);
        g.connect(shaper);
        osc.start(at);
        osc.stop(at + 0.85);
      }
    }
    applyEnvelope(out.gain, { at, attack: 0.015, hold: 0.35, decay: 0.4, peak: 0.5, sustain: 0.65 });
  }

  stop(): void {
    if (!this.running) return;
    this.running = false;
    const t = this.engine.ctx.currentTime;
    ramp(this.swellGain.gain, 0, t, 0.4);
    ramp(this.sampleGain.gain, 0, t, 0.3);
    for (const source of this.sources) source.stop(t + 0.5);
    this.sampleBed?.stop(t);
    this.sampleBed = null;
    this.samplesArmed = false;
  }
}

function ramp(param: AudioParam, value: number, at: number, seconds: number): void {
  cancelFrom(param, at);
  param.linearRampToValueAtTime(value, at + Math.max(seconds, 0.005));
}

function vendorRasp(samples = 512): Float32Array<ArrayBuffer> {
  const curve = new Float32Array(new ArrayBuffer(samples * Float32Array.BYTES_PER_ELEMENT));
  for (let i = 0; i < samples; i++) {
    const x = (i / (samples - 1)) * 2 - 1;
    curve[i] = Math.tanh(x * 2.6) * 0.9;
  }
  return curve;
}
