import type { AudioEngine } from "../AudioEngine.ts";
import { FIELD_POSITIONS, applyEnvelope, noiseBurst, spatialPanner } from "./shared.ts";

/**
 * Plate tick — a short, bright click at the moment the ball crosses the plate.
 *
 * Learning cue for Rookie/Pro. Lives on the field bus so crowd focus leaves it
 * clear and the AM chain never softens it into mush. Not part of the booth.
 */
export function playPlateTick(engine: AudioEngine, at: number): void {
  const { ctx } = engine;
  const panner = spatialPanner(ctx, FIELD_POSITIONS.plate);
  panner.connect(engine.busInput("field"));

  noiseBurst(engine, panner, {
    at,
    duration: 0.028,
    color: "white",
    frequency: 4200,
    q: 2.4,
    peak: 0.55,
    attack: 0.001,
  });

  const ping = ctx.createOscillator();
  ping.type = "sine";
  ping.frequency.setValueAtTime(1880, at);
  ping.frequency.exponentialRampToValueAtTime(980, at + 0.04);

  const gain = ctx.createGain();
  ping.connect(gain);
  gain.connect(panner);

  const end = applyEnvelope(gain.gain, {
    at,
    attack: 0.001,
    decay: 0.045,
    peak: 0.38,
  });
  ping.start(at);
  ping.stop(end + 0.02);
}
