/**
 * Session length / role-lock / practice / series / playoff mode — persisted gate choices.
 *
 * Mode union: exhibition | practice | series | playoff.
 * Season uses `campaignKind: "season"` + `seasonSchedule` / `seasonUnit` beside mode so
 * Series, Playoff, and Season merge without renaming fields. Campaign kinds on GameSave
 * remain discriminated: series | season | playoff | challenge.
 *
 * BR-6 challenges use `challengeId` (not a new SessionMode) so bullpen / series
 * agents can keep extending mode without collisions.
 */

import {
  applyChallengeSession,
  isChallengeId,
  type ChallengeId,
} from "./Challenges.ts";

export type SessionLength = 3 | 6 | 9;
export type RoleLock = "both" | "bat" | "pitch";
export type SessionMode = "exhibition" | "practice" | "series" | "playoff";
/** Season stays on campaignKind; series/playoff own SessionMode; challenges use challengeId. */
export type CampaignKind = "none" | "season";
/** 3 for short series seasons; 6 / 12 for game or series slates. */
export type SeasonScheduleOption = 3 | 6 | 12;
/** Season of single games vs Bo3 series slots. */
export type SeasonUnit = "game" | "series";
/** Playoff depth: single pennant Bo3, or Bo3 → Bo5 bracket. */
export type PlayoffFormat = "pennant" | "bracket";

export interface SessionOptions {
  mode: SessionMode;
  length: SessionLength;
  roleLock: RoleLock;
  campaignKind: CampaignKind;
  /** N schedule slots when campaignKind === "season". Ignored otherwise. */
  seasonSchedule: SeasonScheduleOption;
  /** Season of single games vs Bo3 series slots. */
  seasonUnit: SeasonUnit;
  /** Playoff depth when mode === "playoff". */
  playoffFormat: PlayoffFormat;
  /** BR-6 authored situation — `"none"` when not in a challenge. */
  challengeId: ChallengeId | "none";
}

const STORAGE_KEY = "botn.sessionOptions";

const DEFAULTS: SessionOptions = {
  mode: "exhibition",
  length: 9,
  roleLock: "both",
  campaignKind: "none",
  seasonSchedule: 6,
  seasonUnit: "game",
  playoffFormat: "bracket",
  challengeId: "none",
};

export function isSessionLength(value: unknown): value is SessionLength {
  return value === 3 || value === 6 || value === 9;
}

export function isRoleLock(value: unknown): value is RoleLock {
  return value === "both" || value === "bat" || value === "pitch";
}

export function isSessionMode(value: unknown): value is SessionMode {
  return (
    value === "exhibition" ||
    value === "practice" ||
    value === "series" ||
    value === "playoff"
  );
}

export function isCampaignKind(value: unknown): value is CampaignKind {
  return value === "none" || value === "season";
}

export function isSeasonScheduleOption(value: unknown): value is SeasonScheduleOption {
  return value === 3 || value === 6 || value === 12;
}

export function isSeasonUnit(value: unknown): value is SeasonUnit {
  return value === "game" || value === "series";
}

export function isPlayoffFormat(value: unknown): value is PlayoffFormat {
  return value === "pennant" || value === "bracket";
}

export function normalizeSessionOptions(
  partial: Partial<SessionOptions> & Pick<SessionOptions, "mode" | "length" | "roleLock">,
): SessionOptions {
  let mode: SessionMode = isSessionMode(partial.mode) ? partial.mode : DEFAULTS.mode;
  let campaignKind: CampaignKind = isCampaignKind(partial.campaignKind)
    ? partial.campaignKind
    : DEFAULTS.campaignKind;
  let challengeId: ChallengeId | "none" =
    partial.challengeId === "none" || partial.challengeId === undefined
      ? "none"
      : isChallengeId(partial.challengeId)
        ? partial.challengeId
        : "none";
  let seasonUnit: SeasonUnit = isSeasonUnit(partial.seasonUnit)
    ? partial.seasonUnit
    : DEFAULTS.seasonUnit;
  let playoffFormat: PlayoffFormat = isPlayoffFormat(partial.playoffFormat)
    ? partial.playoffFormat
    : DEFAULTS.playoffFormat;
  let seasonSchedule: SeasonScheduleOption = isSeasonScheduleOption(partial.seasonSchedule)
    ? partial.seasonSchedule
    : DEFAULTS.seasonSchedule;

  // Mutual exclusion: series / playoff / practice never wrap a season schedule.
  if (mode === "practice" || mode === "series" || mode === "playoff") campaignKind = "none";
  if (campaignKind === "season" && (mode === "series" || mode === "playoff")) {
    mode = "exhibition";
  }

  // Series seasons default to a shorter slate when someone left 12 from games mode.
  if (campaignKind === "season" && seasonUnit === "series" && seasonSchedule === 12) {
    seasonSchedule = 6;
  }
  // Game seasons do not use the 3-slot option (gate hides it).
  if (campaignKind === "season" && seasonUnit === "game" && seasonSchedule === 3) {
    seasonSchedule = 6;
  }

  // Challenges own length / role / mode; clear season + series/playoff wrappers.
  const challengeBits = applyChallengeSession(challengeId);
  if (challengeBits) {
    campaignKind = "none";
    mode = challengeBits.mode;
    return {
      mode,
      length: challengeBits.length,
      roleLock: challengeBits.roleLock,
      campaignKind,
      seasonSchedule,
      seasonUnit,
      playoffFormat,
      challengeId,
    };
  }

  // Picking series / playoff / season clears any stale challenge id.
  if (mode === "series" || mode === "playoff" || campaignKind === "season") {
    challengeId = "none";
  }

  return {
    mode,
    length: isSessionLength(partial.length) ? partial.length : DEFAULTS.length,
    roleLock: isRoleLock(partial.roleLock) ? partial.roleLock : DEFAULTS.roleLock,
    campaignKind,
    seasonSchedule,
    seasonUnit,
    playoffFormat,
    challengeId,
  };
}

export function loadSessionOptions(): SessionOptions {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULTS };
    const parsed = JSON.parse(raw) as Partial<SessionOptions>;
    if (!isSessionMode(parsed.mode) || !isSessionLength(parsed.length) || !isRoleLock(parsed.roleLock)) {
      return { ...DEFAULTS };
    }
    return normalizeSessionOptions(parsed as SessionOptions);
  } catch {
    return { ...DEFAULTS };
  }
}

export function saveSessionOptions(options: SessionOptions): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(options));
  } catch {
    /* private browsing */
  }
}

export function describeSession(options: SessionOptions): string {
  if (options.challengeId !== "none") {
    // Lazy title via id; Challenges.getChallenge would cycle-import if used at top.
    const labels: Record<ChallengeId, string> = {
      "hold-ninth": "Hold the ninth",
      "bottom-ninth": "Bottom of the Ninth",
      "escape-act": "Escape act",
      "practice-cage-plus": "Practice cage++",
      "tie-breaker": "Tie-breaker",
      "traffic-jam": "Traffic jam",
    };
    return `Challenge: ${labels[options.challengeId]}.`;
  }
  if (options.mode === "practice") return "Practice cage — Rookie fastballs on the beat.";
  const role =
    options.roleLock === "bat"
      ? " batting only"
      : options.roleLock === "pitch"
        ? " pitching only"
        : "";
  if (options.mode === "series") {
    return `Best-of-3 series, ${options.length}-inning games${role}.`;
  }
  if (options.mode === "playoff") {
    if (options.playoffFormat === "pennant") {
      return `Pennant playoffs (best of 3), ${options.length}-inning games${role}.`;
    }
    return `Playoff bracket (Bo3 pennant → Bo5 final), ${options.length}-inning games${role}.`;
  }
  const base = `${options.length}-inning exhibition${role}`;
  if (options.campaignKind === "season") {
    const unitLabel = options.seasonUnit === "series" ? "series" : "game";
    return `${options.seasonSchedule}-${unitLabel} season · ${base}.`;
  }
  return `${base}.`;
}
