import type { Phrase, SpeakHandle, VoiceBackend } from "./VoiceBackend.ts";

/**
 * CommentaryQueue — one voice bus, several people who want to talk.
 *
 * Radio has a hard constraint that text logs don't: two people talking at once is
 * unintelligible. So phrases are laid end to end on the audio clock, and when
 * something urgent arrives the queue *takes the microphone back* rather than
 * waiting politely.
 *
 * Priorities (lower wins):
 *   0  play-by-play — the ball is doing something, this always gets through
 *   1  umpire relay
 *   2  colour commentary — fills dead air, and is the first thing dropped
 *   3  utility (Eric) — vendors / station IDs; first dropped for anything urgent
 *
 * The realistic failure this prevents: colour man starts a forty-word thought about
 * the shift, next pitch is a home run, and the call arrives four seconds late on
 * top of a crowd that already gave it away.
 */

export const PRIORITY = {
  playByPlay: 0,
  umpire: 1,
  color: 2,
  utility: 3,
} as const;

/** Beat of air between consecutive phrases. */
const GAP_SEC = 0.22;

interface Queued {
  priority: number;
  startAt: number;
  endAt: number;
  handle: SpeakHandle;
}

export interface SayOptions {
  priority?: number;
  /** Earliest audio-clock time this may be delivered. */
  notBefore: number;
  /**
   * Drop everything still undelivered before queuing this.
   *
   * The booth needs roughly seven seconds to describe a pitch that takes four
   * seconds to throw. Without a preemption point the queue falls three seconds
   * further behind on every pitch, and by the second inning the announcer is
   * calling a play from twenty seconds ago over a crowd that already reacted.
   *
   * Setting this on the delivery call at the top of each pitch bounds the backlog
   * to exactly one pitch: whatever the booth hasn't got to by the time the next
   * ball is in the air is no longer worth saying.
   */
  preempt?: boolean;
}

export class CommentaryQueue {
  private readonly backend: VoiceBackend;
  private readonly now: () => number;
  private queued: Queued[] = [];

  constructor(backend: VoiceBackend, now: () => number) {
    this.backend = backend;
    this.now = now;
  }

  /** Audio-clock time at which the voice bus next comes free. */
  get busyUntil(): number {
    return this.queued.reduce((max, item) => Math.max(max, item.endAt), 0);
  }

  say(phrase: Phrase, options: SayOptions): number {
    const priority = options.priority ?? PRIORITY.playByPlay;
    this.prune();

    if (options.preempt === true) {
      this.cancelUndelivered();
    } else {
      // Anything less important that hasn't been delivered yet gives up its slot.
      this.cancelBelow(priority);
    }

    const startAt = Math.max(options.notBefore, this.busyUntil + GAP_SEC, this.now() + 0.02);
    const handle = this.backend.speak(phrase, startAt);
    this.queued.push({ priority, startAt, endAt: startAt + handle.durationSec, handle });
    return startAt + handle.durationSec;
  }

  /** Convenience for a run of phrases that must stay in order. */
  sayAll(phrases: readonly Phrase[], options: SayOptions): number {
    let end = options.notBefore;
    for (const phrase of phrases) {
      end = this.say(phrase, { ...options, notBefore: end });
    }
    return end;
  }

  /** Drop undelivered phrases strictly less important than `priority`. */
  cancelBelow(priority: number): void {
    const now = this.now();
    this.queued = this.queued.filter((item) => {
      if (item.priority <= priority || item.startAt <= now) return true;
      item.handle.cancel();
      return false;
    });
  }

  /** Drop every phrase that has not started yet, whatever its priority. */
  cancelUndelivered(): void {
    const now = this.now();
    this.queued = this.queued.filter((item) => {
      if (item.startAt <= now) return true;
      item.handle.cancel();
      return false;
    });
  }

  clear(): void {
    for (const item of this.queued) item.handle.cancel();
    this.queued = [];
  }

  private prune(): void {
    const now = this.now();
    this.queued = this.queued.filter((item) => item.endAt > now);
  }
}
