/**
 * Local “today’s broadcast” attempt streak (days attempted, not wins).
 * Audio-first: gate copy only — no leaderboard.
 */

import { dateHashKey } from "./Challenges.ts";

export const CHALLENGE_STREAK_KEY = "botn.challengeStreak.v1";

export interface ChallengeStreakV1 {
  readonly v: 1;
  /** UTC YYYYMMDD of the last recorded attempt. */
  readonly lastAttemptKey: number;
  /** Consecutive calendar days with at least one attempt. */
  readonly streak: number;
  /** Lifetime days with at least one attempt. */
  readonly daysAttempted: number;
}

const EMPTY: ChallengeStreakV1 = {
  v: 1,
  lastAttemptKey: 0,
  streak: 0,
  daysAttempted: 0,
};

export function loadChallengeStreak(): ChallengeStreakV1 {
  try {
    const raw = localStorage.getItem(CHALLENGE_STREAK_KEY);
    if (!raw) return { ...EMPTY };
    const parsed = JSON.parse(raw) as Partial<ChallengeStreakV1>;
    if (parsed.v !== 1) return { ...EMPTY };
    if (typeof parsed.lastAttemptKey !== "number") return { ...EMPTY };
    if (typeof parsed.streak !== "number" || parsed.streak < 0) return { ...EMPTY };
    if (typeof parsed.daysAttempted !== "number" || parsed.daysAttempted < 0) return { ...EMPTY };
    return {
      v: 1,
      lastAttemptKey: parsed.lastAttemptKey,
      streak: Math.floor(parsed.streak),
      daysAttempted: Math.floor(parsed.daysAttempted),
    };
  } catch {
    return { ...EMPTY };
  }
}

export function writeChallengeStreak(streak: ChallengeStreakV1): void {
  try {
    localStorage.setItem(CHALLENGE_STREAK_KEY, JSON.stringify(streak));
  } catch {
    /* private browsing */
  }
}

/** Yesterday’s UTC YYYYMMDD key (handles month/year wrap). */
export function previousDateHashKey(key: number): number {
  const y = Math.floor(key / 10_000);
  const m = Math.floor((key % 10_000) / 100);
  const d = key % 100;
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() - 1);
  return dateHashKey(dt);
}

/**
 * Record one attempt for the calendar day. Same-day repeats are no-ops.
 * Consecutive days bump streak; a gap resets streak to 1.
 */
export function recordChallengeAttempt(date: Date = new Date()): ChallengeStreakV1 {
  const key = dateHashKey(date);
  const prev = loadChallengeStreak();
  if (prev.lastAttemptKey === key) return prev;
  const consecutive = prev.lastAttemptKey === previousDateHashKey(key);
  const next: ChallengeStreakV1 = {
    v: 1,
    lastAttemptKey: key,
    streak: consecutive ? prev.streak + 1 : 1,
    daysAttempted: prev.daysAttempted + 1,
  };
  writeChallengeStreak(next);
  return next;
}

export function describeChallengeStreak(
  streak: ChallengeStreakV1,
  date: Date = new Date(),
): string {
  if (streak.daysAttempted <= 0) return "No streak yet — tune in today.";
  const today = dateHashKey(date);
  const live =
    streak.lastAttemptKey === today || streak.lastAttemptKey === previousDateHashKey(today);
  if (!live) {
    return `${streak.daysAttempted} day${streak.daysAttempted === 1 ? "" : "s"} attempted. Start a new streak today.`;
  }
  if (streak.streak <= 1) {
    return streak.lastAttemptKey === today
      ? "Attempted today. Come back tomorrow to start a streak."
      : "1-day streak — tune in today to keep it going.";
  }
  return `${streak.streak}-day streak · ${streak.daysAttempted} day${streak.daysAttempted === 1 ? "" : "s"} attempted.`;
}
