import { stampOf, type SwingInput } from "../timing/SwingInput.ts";

/**
 * Swing / Release controls for phones and screen readers.
 * Feeds the same SwingInput path as Space / background taps.
 *
 * The fixed FAB stays sighted/mobile-first (hidden when inactive).
 * The rail button stays in the accessibility tree whenever batting/pitching
 * so keyboard and SR users always have a named control to activate.
 */
export class ActionPad {
  private readonly fab: HTMLButtonElement;
  private readonly rail: HTMLButtonElement;
  private readonly input: SwingInput;
  private role: "bat" | "pitch" = "bat";
  private enabled = false;
  /** True after pointerdown so the following click does not double-fire. */
  private pointerHandled = false;

  constructor(fab: HTMLButtonElement, rail: HTMLButtonElement, input: SwingInput) {
    this.fab = fab;
    this.rail = rail;
    this.input = input;
    for (const button of [this.fab, this.rail]) {
      button.type = "button";
      button.setAttribute("data-timing-action", "true");
      button.addEventListener("pointerdown", this.onPointerDown);
      button.addEventListener("click", this.onClick);
    }
    this.fab.classList.add("action-fab");
    this.rail.classList.add("timing-action");
    this.syncLabel();
    this.setEnabled(false);
  }

  setRole(role: "bat" | "pitch"): void {
    this.role = role;
    this.syncLabel();
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    // FAB: hide when idle (thumb zone only matters mid-game on phones).
    this.fab.disabled = !enabled;
    this.fab.hidden = !enabled;
    // Rail: stay present for SR/keyboard — disabled + described when inactive.
    this.rail.hidden = false;
    this.rail.disabled = !enabled;
    this.rail.setAttribute("aria-disabled", enabled ? "false" : "true");
    this.syncLabel();
  }

  get isEnabled(): boolean {
    return this.enabled;
  }

  private syncLabel(): void {
    const label = this.role === "bat" ? "Swing" : "Release";
    for (const button of [this.fab, this.rail]) {
      button.textContent = label;
    }
    this.fab.setAttribute("aria-label", `${label} — tap or press Space`);
    if (this.enabled) {
      this.rail.setAttribute(
        "aria-label",
        this.role === "bat"
          ? "Swing — activate on beat five during the pitch, or press Space"
          : "Release — activate on beat four during the windup, or press Space",
      );
    } else {
      this.rail.setAttribute(
        "aria-label",
        this.role === "bat"
          ? "Swing — available after you start the at-bat and the pitch is live"
          : "Release — available after you start pitching and the windup begins",
      );
    }
  }

  private readonly onPointerDown = (event: PointerEvent): void => {
    event.preventDefault();
    event.stopPropagation();
    this.pointerHandled = true;
    this.input.injectSwing(stampOf(event, () => performance.now()));
  };

  private readonly onClick = (event: MouseEvent): void => {
    // Keyboard / SR activation synthesizes click without a prior pointerdown.
    if (this.pointerHandled) {
      this.pointerHandled = false;
      event.preventDefault();
      return;
    }
    event.preventDefault();
    this.input.injectSwing(stampOf(event, () => performance.now()));
  };

  dispose(): void {
    for (const button of [this.fab, this.rail]) {
      button.removeEventListener("pointerdown", this.onPointerDown);
      button.removeEventListener("click", this.onClick);
    }
  }
}
