/**
 * Gate resume / continue copy and abort (clear live save + campaign shells).
 *
 * Mid-game: Resume restores GameSave.
 * Between games (series / playoff / season): Continue uses the durable campaign
 * key when no live game is on disk — Play Ball / New game still aborts.
 */

import type { DifficultyId } from "./Difficulty.ts";
import { getChallenge, isChallengeCampaign } from "./Challenges.ts";
import { clearGameSave, describeGameSave, loadGameSave, type GameSaveV1 } from "./GameSave.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import type { PlayoffFormat, SessionOptions } from "./SessionOptions.ts";
import {
  clearPlayoff,
  isPlayoffCampaign,
  loadPlayoff,
  PlayoffState,
} from "./PlayoffState.ts";
import {
  clearSeason,
  describeSeasonStandings,
  isSeasonCampaign,
  isSeasonComplete,
  loadSeason,
  type SeasonPersist,
} from "./SeasonState.ts";
import {
  clearSeries,
  isSeriesCampaign,
  loadSeries,
  SeriesState,
} from "./SeriesState.ts";

export function abortAllProgress(): void {
  clearGameSave();
  clearSeries();
  clearPlayoff();
  clearSeason();
}

export interface ResumeGateModel {
  visible: boolean;
  buttonLabel: string;
  hint: string;
  playBallLabel: "Play Ball" | "New game";
  save: GameSaveV1 | null;
  /** True when the next contest should load an incomplete campaign shell. */
  continueCampaign: boolean;
}

export interface ContinueCampaignPatch {
  session: SessionOptions;
  playerSide: PlayerSide;
  difficultyId: DifficultyId;
}

export function loadResumeGateModel(): ResumeGateModel {
  return describeResumeGate({
    save: loadGameSave(),
    playoff: loadPlayoff(),
    series: loadSeries(),
    season: loadSeason(),
  });
}

export function describeResumeGate(args: {
  save: GameSaveV1 | null;
  playoff: PlayoffState | null;
  series: SeriesState | null;
  season: SeasonPersist | null;
}): ResumeGateModel {
  const playoff = args.playoff && !args.playoff.isComplete() ? args.playoff : null;
  const series = args.series && !args.series.isComplete() ? args.series : null;
  const season = args.season && !isSeasonComplete(args.season) ? args.season : null;

  if (args.save) {
    const summary = describeGameSave(args.save);
    const campaignNote = campaignNoteForSave(args.save, { playoff, series, season });
    return {
      visible: true,
      buttonLabel: resumeButtonLabel(args.save, { playoff, series, season }),
      hint: `Saved game: ${summary}.${campaignNote} Resume continues that broadcast; Play Ball starts fresh and clears series, playoff, season, and challenge progress.`,
      playBallLabel: "New game",
      save: args.save,
      continueCampaign: false,
    };
  }

  if (playoff) {
    return {
      visible: true,
      buttonLabel: "Continue playoff",
      hint: `${playoff.scoreLine()} Continue the next game of this playoff; Play Ball starts a new broadcast and clears this bracket.`,
      playBallLabel: "New game",
      save: null,
      continueCampaign: true,
    };
  }

  if (season) {
    return {
      visible: true,
      buttonLabel: "Continue season",
      hint: `${describeSeasonStandings(season)} Continue the next contest; Play Ball starts fresh and clears this season.`,
      playBallLabel: "New game",
      save: null,
      continueCampaign: true,
    };
  }

  if (series) {
    return {
      visible: true,
      buttonLabel: "Continue series",
      hint: `${series.scoreLine()} Continue the next game of this series; Play Ball starts fresh and clears the series.`,
      playBallLabel: "New game",
      save: null,
      continueCampaign: true,
    };
  }

  return {
    visible: false,
    buttonLabel: "Resume broadcast",
    hint: "",
    playBallLabel: "Play Ball",
    save: null,
    continueCampaign: false,
  };
}

/** Session + side to restore when continuing a campaign with no live GameSave. */
export function continueCampaignPatch(): ContinueCampaignPatch | null {
  const playoff = loadPlayoff();
  if (playoff && !playoff.isComplete()) {
    const s = playoff.series;
    return {
      playerSide: s.playerSide,
      difficultyId: s.difficultyId,
      session: {
        mode: "playoff",
        length: s.length,
        roleLock: s.roleLock,
        campaignKind: "none",
        seasonSchedule: 6,
        seasonUnit: "game",
        playoffFormat: playoffFormatOf(playoff),
        challengeId: "none",
      },
    };
  }

  const season = loadSeason();
  if (season && !isSeasonComplete(season)) {
    return {
      playerSide: season.playerSide,
      difficultyId: season.difficultyId,
      session: {
        mode: "exhibition",
        length: season.length,
        roleLock: season.roleLock,
        campaignKind: "season",
        seasonSchedule: season.scheduleLength,
        seasonUnit: season.unit ?? "game",
        playoffFormat: "bracket",
        challengeId: "none",
      },
    };
  }

  const series = loadSeries();
  if (series && !series.isComplete()) {
    return {
      playerSide: series.playerSide,
      difficultyId: series.difficultyId,
      session: {
        mode: "series",
        length: series.length,
        roleLock: series.roleLock,
        campaignKind: "none",
        seasonSchedule: 6,
        seasonUnit: "game",
        playoffFormat: "bracket",
        challengeId: "none",
      },
    };
  }

  return null;
}

function playoffFormatOf(playoff: PlayoffState): PlayoffFormat {
  return playoff.rounds.length > 1 ? "bracket" : "pennant";
}

function resumeButtonLabel(
  save: GameSaveV1,
  shells: {
    playoff: PlayoffState | null;
    series: SeriesState | null;
    season: SeasonPersist | null;
  },
): string {
  if (isChallengeCampaign(save.campaign) || save.session.challengeId !== "none") {
    return "Resume challenge";
  }
  if (isPlayoffCampaign(save.campaign) || shells.playoff || save.session.mode === "playoff") {
    return "Resume playoff";
  }
  if (isSeasonCampaign(save.campaign) || shells.season || save.session.campaignKind === "season") {
    return "Resume season";
  }
  if (isSeriesCampaign(save.campaign) || shells.series || save.session.mode === "series") {
    return "Resume series";
  }
  return "Resume broadcast";
}

function campaignNoteForSave(
  save: GameSaveV1,
  shells: {
    playoff: PlayoffState | null;
    series: SeriesState | null;
    season: SeasonPersist | null;
  },
): string {
  if (isPlayoffCampaign(save.campaign) || shells.playoff) {
    const playoff =
      shells.playoff ?? (isPlayoffCampaign(save.campaign) ? new PlayoffState(save.campaign) : null);
    return playoff ? ` ${playoff.scoreLine()}` : "";
  }
  if (isChallengeCampaign(save.campaign)) {
    return ` Challenge: ${getChallenge(save.campaign.id).title}.`;
  }
  if (isSeasonCampaign(save.campaign) || shells.season) {
    const season =
      shells.season ?? (isSeasonCampaign(save.campaign) ? save.campaign.season : null);
    return season ? ` ${describeSeasonStandings(season)}` : "";
  }
  if (isSeriesCampaign(save.campaign) || shells.series) {
    const series =
      shells.series ?? (isSeriesCampaign(save.campaign) ? new SeriesState(save.campaign) : null);
    return series ? ` ${series.scoreLine()}` : "";
  }
  return "";
}
