import { ClockBridge } from "./ClockBridge.ts";
import { NoiseFactory } from "./NoiseFactory.ts";
import { SampleBank } from "./SampleBank.ts";

/**
 * AudioEngine — the mixing console.
 *
 * Four isolated buses, per the brief:
 *
 *   announcer ─┐                                        ┌─ radio chain ─┐
 *              ├─ broadcast sum ─ (wet/dry crossfade) ──┤               ├─┐
 *   color ─────┘                                        └─ dry ─────────┘ │
 *                                                                          ├─ master ─ limiter ─ out
 *   crowd ───── duck gain ─────────────────────────────────────────────────┤
 *   field ─────────────────────────────────────────────────────────────────┘
 *
 * The two voice buses share one radio filter chain rather than each owning a copy:
 * in a real broadcast both mics hit the same transmitter, and per-bus gain stays
 * independent anyway because the gain nodes sit upstream of the sum.
 *
 * Only the crowd ducks under play-by-play. The field bus carries the delivery
 * pulse, the ball, the bat, and the umpire — ducking it under the booth is what
 * made timing cues disappear the moment anyone started talking.
 */

export type BusName = "announcer" | "color" | "crowd" | "field";

export interface Bus {
  /** Connect voices here. */
  readonly input: GainNode;
  /** Set the user-facing level for this bus (0..1), optionally ramped. */
  setLevel(value: number, rampSeconds?: number): void;
  readonly level: number;
}

const DEFAULT_LEVELS: Record<BusName, number> = {
  announcer: 1.0,
  // Match PBP — Brian's takes already sit softer than Adam's; don't duck the bus too.
  color: 1.0,
  // Lowered from 0.55: the crowd is the loudest continuous thing in the mix and it
  // was masking the delivery cues the batter times off.
  crowd: 0.4,
  field: 0.95,
};

/** How far the crowd drops while someone is talking. */
const DUCK_DEPTH = 0.35;
const DUCK_ATTACK = 0.05;
const DUCK_RELEASE = 0.3;

/** How far the crowd alone drops while a pitch is in the air. */
const FOCUS_DEPTH = 0.4;
const FOCUS_ATTACK = 0.12;
const FOCUS_RELEASE = 0.5;

export class AudioEngine {
  readonly ctx: AudioContext;
  readonly clock: ClockBridge;
  readonly noise: NoiseFactory;
  readonly samples: SampleBank;

  private readonly buses = new Map<BusName, BusImpl>();
  private readonly duckParams: AudioParam[] = [];
  private duckReleaseAt = 0;
  private readonly crowdFocus: GainNode;
  private focusReleaseAt = 0;

  private readonly master: GainNode;
  private readonly wetGain: GainNode;
  private readonly dryGain: GainNode;
  private radioEnabled = true;

  constructor() {
    // 'interactive' asks the platform for the smallest buffer it can manage.
    // On a timing game the latency matters more than the power draw.
    this.ctx = new AudioContext({ latencyHint: "interactive" });
    this.clock = new ClockBridge(this.ctx);
    this.noise = new NoiseFactory(this.ctx);
    this.samples = new SampleBank();

    // --- Output stage -------------------------------------------------------
    // A limiter, not for loudness, but because a bat crack landing on top of a
    // level-5 crowd and an excited announcer will otherwise clip the sum.
    const limiter = this.ctx.createDynamicsCompressor();
    limiter.threshold.value = -6;
    limiter.knee.value = 6;
    limiter.ratio.value = 12;
    limiter.attack.value = 0.003;
    limiter.release.value = 0.25;
    limiter.connect(this.ctx.destination);

    this.master = this.ctx.createGain();
    this.master.gain.value = 0.8;
    this.master.connect(limiter);

    // --- Broadcast (voice) path --------------------------------------------
    const broadcastSum = this.ctx.createGain();

    const radioChain = buildRadioChain(this.ctx);
    this.wetGain = this.ctx.createGain();
    this.dryGain = this.ctx.createGain();
    this.wetGain.gain.value = 1;
    this.dryGain.gain.value = 0;

    broadcastSum.connect(this.wetGain);
    this.wetGain.connect(radioChain.input);
    radioChain.output.connect(this.master);
    broadcastSum.connect(this.dryGain);
    this.dryGain.connect(this.master);

    // Announcer: forced mono and dead centre — the anchor of the mix.
    const announcer = this.createBus("announcer");
    announcer.input.channelCount = 1;
    announcer.input.channelCountMode = "explicit";
    announcer.input.connect(broadcastSum);

    // Colour commentator: parked slightly off-axis so the ear can tell the two
    // voices apart without either one moving.
    const color = this.createBus("color");
    const colorPan = this.ctx.createStereoPanner();
    colorPan.pan.value = 0.25;
    color.input.connect(colorPan);
    colorPan.connect(broadcastSum);

    // --- Ambience and field paths ------------------------------------------
    // The crowd passes through two gains in series rather than one. Voice ducking
    // and pitch focus overlap constantly, and two automation curves fighting over a
    // single AudioParam produce whichever one was scheduled last — not the product
    // of the two. In series they multiply, which is what "duck for both reasons"
    // should mean.
    const crowd = this.createBus("crowd");
    const crowdDuck = this.ctx.createGain();
    this.crowdFocus = this.ctx.createGain();
    crowd.input.connect(crowdDuck);
    crowdDuck.connect(this.crowdFocus);
    this.crowdFocus.connect(this.master);
    this.duckParams.push(crowdDuck.gain);

    const field = this.createBus("field");
    field.input.connect(this.master);
  }

  private createBus(name: BusName): BusImpl {
    const bus = new BusImpl(this.ctx, DEFAULT_LEVELS[name]);
    this.buses.set(name, bus);
    return bus;
  }

  bus(name: BusName): Bus {
    const found = this.buses.get(name);
    if (!found) throw new Error(`Unknown bus: ${name}`);
    return found;
  }

  /** Convenience for voices that need a raw node to connect to. */
  busInput(name: BusName): GainNode {
    return (this.bus(name) as BusImpl).input;
  }

  get currentTime(): number {
    return this.ctx.currentTime;
  }

  /**
   * Resume the context. Must be called from a user gesture — browsers start
   * every AudioContext suspended. Resets the clock bridge, since `currentTime`
   * freezes while suspended and every retained sample is therefore stale.
   */
  async resume(): Promise<void> {
    if (this.ctx.state !== "running") {
      await this.ctx.resume();
    }
    this.noise.warmUp();
    this.clock.reset();
    this.clock.startAutoSampling();
  }

  setMasterLevel(value: number): void {
    rampParam(this.ctx, this.master.gain, clamp01(value), 0.03);
  }

  get masterLevel(): number {
    return this.master.gain.value;
  }

  /** Crossfade the AM bandpass in or out, so it can be A/B'd while playing. */
  setRadioFilter(enabled: boolean): void {
    if (enabled === this.radioEnabled) return;
    this.radioEnabled = enabled;
    const t = this.ctx.currentTime;
    rampParam(this.ctx, this.wetGain.gain, enabled ? 1 : 0, 0.04, t);
    rampParam(this.ctx, this.dryGain.gain, enabled ? 0 : 1, 0.04, t);
  }

  get radioFilterEnabled(): boolean {
    return this.radioEnabled;
  }

  /**
   * Duck the crowd under a voice. Field stays put — see the class header.
   *
   * Overlapping calls extend the hold rather than restarting the envelope, so a
   * run of short phrases doesn't pump the crowd up and down between each one.
   */
  duckFor(startContextTime: number, durationSeconds: number): void {
    const start = Math.max(startContextTime, this.ctx.currentTime);
    const releaseAt = start + durationSeconds;
    if (releaseAt <= this.duckReleaseAt) return;
    this.duckReleaseAt = releaseAt;

    for (const param of this.duckParams) {
      cancelFrom(param, start);
      param.linearRampToValueAtTime(DUCK_DEPTH, start + DUCK_ATTACK);
      const holdUntil = Math.max(start + DUCK_ATTACK, releaseAt);
      param.setValueAtTime(DUCK_DEPTH, holdUntil);
      param.linearRampToValueAtTime(1, holdUntil + DUCK_RELEASE);
    }
  }

  /**
   * Pull the crowd down while a pitch is in the air, leaving the field in the clear.
   *
   * Not what a broadcast does — but a broadcast is not asking you to place a
   * transient to within 30 ms. The delivery pulse and the ball release are the only
   * information the batter gets, and a full-level crowd bed sits right on top of
   * them. Note this ducks the crowd only: routing the field bus through the same
   * automation would duck the pitch along with everything else.
   */
  focusOnField(startContextTime: number, durationSeconds: number): void {
    const start = Math.max(startContextTime, this.ctx.currentTime);
    const releaseAt = start + durationSeconds;
    if (releaseAt <= this.focusReleaseAt) return;
    this.focusReleaseAt = releaseAt;

    const param = this.crowdFocus.gain;
    cancelFrom(param, start);
    param.linearRampToValueAtTime(FOCUS_DEPTH, start + FOCUS_ATTACK);
    const holdUntil = Math.max(start + FOCUS_ATTACK, releaseAt);
    param.setValueAtTime(FOCUS_DEPTH, holdUntil);
    param.linearRampToValueAtTime(1, holdUntil + FOCUS_RELEASE);
  }
}

class BusImpl implements Bus {
  readonly input: GainNode;
  private readonly ctx: AudioContext;

  constructor(ctx: AudioContext, initialLevel: number) {
    this.ctx = ctx;
    this.input = ctx.createGain();
    this.input.gain.value = initialLevel;
  }

  setLevel(value: number, rampSeconds = 0.03): void {
    rampParam(this.ctx, this.input.gain, clamp01(value), rampSeconds);
  }

  get level(): number {
    return this.input.gain.value;
  }
}

/**
 * The AM radio sound: band-limit hard, add a little grit, make up the level.
 * 300 Hz–3.4 kHz is the classic telephone/AM voice band from the brief.
 */
function buildRadioChain(ctx: AudioContext): { input: AudioNode; output: AudioNode } {
  const highpass = ctx.createBiquadFilter();
  highpass.type = "highpass";
  highpass.frequency.value = 300;
  highpass.Q.value = 0.707;

  // Two poles of lowpass rather than one: a single 12 dB/oct slope still leaks
  // enough top end that the result reads as "muffled" instead of "on the radio".
  const lowpass1 = ctx.createBiquadFilter();
  lowpass1.type = "lowpass";
  lowpass1.frequency.value = 3400;
  lowpass1.Q.value = 0.707;

  const lowpass2 = ctx.createBiquadFilter();
  lowpass2.type = "lowpass";
  lowpass2.frequency.value = 3400;
  lowpass2.Q.value = 0.707;

  // A presence bump around 2 kHz is what makes a bandlimited voice cut through
  // a crowd bed instead of disappearing into it.
  const presence = ctx.createBiquadFilter();
  presence.type = "peaking";
  presence.frequency.value = 2000;
  presence.Q.value = 1.1;
  presence.gain.value = 6;

  const drive = ctx.createWaveShaper();
  drive.curve = softClipCurve(2.2);
  drive.oversample = "2x";

  const makeup = ctx.createGain();
  makeup.gain.value = 1.15;

  highpass.connect(lowpass1);
  lowpass1.connect(lowpass2);
  lowpass2.connect(presence);
  presence.connect(drive);
  drive.connect(makeup);

  return { input: highpass, output: makeup };
}

// `WaveShaperNode.curve` requires a Float32Array over a plain ArrayBuffer — the
// default `Float32Array` alias also admits SharedArrayBuffer, which it will not take.
function softClipCurve(amount: number, samples = 1024): Float32Array<ArrayBuffer> {
  const curve = new Float32Array(new ArrayBuffer(samples * Float32Array.BYTES_PER_ELEMENT));
  for (let i = 0; i < samples; i++) {
    const x = (i / (samples - 1)) * 2 - 1;
    curve[i] = Math.tanh(x * amount) / Math.tanh(amount);
  }
  return curve;
}

/**
 * Cancel pending automation and pin the param to whatever value it holds at `t`.
 * `cancelAndHoldAtTime` does this correctly; the fallback approximates it with
 * the instantaneous value, which is close enough at the times we call it.
 */
export function cancelFrom(param: AudioParam, t: number): void {
  const holdable = param as AudioParam & { cancelAndHoldAtTime?: (t: number) => void };
  if (typeof holdable.cancelAndHoldAtTime === "function") {
    holdable.cancelAndHoldAtTime(t);
    return;
  }
  param.cancelScheduledValues(t);
  param.setValueAtTime(param.value, t);
}

export function rampParam(
  ctx: BaseAudioContext,
  param: AudioParam,
  value: number,
  seconds: number,
  at?: number,
): void {
  const t = at ?? ctx.currentTime;
  cancelFrom(param, t);
  param.linearRampToValueAtTime(value, t + seconds);
}

function clamp01(v: number): number {
  return Math.min(1, Math.max(0, v));
}
