/**
 * PlayoffState — thin bracket of series (audio drama, not MLB sim).
 *
 * Depth formats:
 * - pennant: single Bo3 “Pennant Series”
 * - bracket: Pennant Bo3 → Championship Bo5 (spoken round transitions)
 *
 * Persist: `botn.playoff.v1` + `GameSave.campaign: { kind: "playoff", ... }`.
 * Each leg reuses SeriesState; do not also write `botn.series.v1` during playoffs.
 */

import type { DifficultyId } from "./Difficulty.ts";
import { isDifficultyId } from "./Difficulty.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import { isPlayerSide } from "./PlayerSide.ts";
import type { PlayoffFormat, RoleLock, SessionLength } from "./SessionOptions.ts";
import { isRoleLock, isSessionLength } from "./SessionOptions.ts";
import {
  SeriesState,
  isSeriesBestOf,
  isSeriesCampaign,
  seriesVenueShort,
  seriesVenueSpoken,
  type SeriesBestOf,
  type SeriesCampaignV1,
  type SeriesGameResult,
} from "./SeriesState.ts";
import { AWAY_TEAM, HOME_TEAM } from "./Teams.ts";

export const PLAYOFF_STORAGE_KEY = "botn.playoff.v1";

export type PlayoffRoundId = "pennant" | "championship";
export type { PlayoffFormat };

export interface PlayoffRoundConfig {
  readonly id: PlayoffRoundId;
  readonly label: string;
  readonly bestOf: SeriesBestOf;
}

/** Single-series pennant (legacy / gate option). */
export const PLAYOFF_BRACKET_PENNANT: readonly PlayoffRoundConfig[] = [
  { id: "pennant", label: "Pennant Series", bestOf: 3 },
];

/** Two-round depth: Bo3 pennant → Bo5 championship. */
export const PLAYOFF_BRACKET_DEPTH: readonly PlayoffRoundConfig[] = [
  { id: "pennant", label: "Pennant Series", bestOf: 3 },
  { id: "championship", label: "Championship Series", bestOf: 5 },
];

/** Default when Mode = Playoff with no format override — deeper bracket. */
export const PLAYOFF_BRACKET_V1: readonly PlayoffRoundConfig[] = PLAYOFF_BRACKET_DEPTH;

export function roundsForPlayoffFormat(format: PlayoffFormat): readonly PlayoffRoundConfig[] {
  return format === "pennant" ? PLAYOFF_BRACKET_PENNANT : PLAYOFF_BRACKET_DEPTH;
}

export interface PlayoffCampaignV1 {
  readonly kind: "playoff";
  readonly v: 1;
  readonly roundIndex: number;
  readonly rounds: readonly PlayoffRoundConfig[];
  /** Nested Best-of-N shell for the current round. */
  readonly series: SeriesCampaignV1;
}

export interface PlayoffCreateArgs {
  playerSide: PlayerSide;
  length: SessionLength;
  roleLock: RoleLock;
  difficultyId: DifficultyId;
  /** Override for tests / gate format. */
  rounds?: readonly PlayoffRoundConfig[];
  format?: PlayoffFormat;
}

function isPlayoffRoundId(value: unknown): value is PlayoffRoundId {
  return value === "pennant" || value === "championship";
}

function isPlayoffRoundConfig(raw: unknown): raw is PlayoffRoundConfig {
  if (!raw || typeof raw !== "object") return false;
  const r = raw as Partial<PlayoffRoundConfig>;
  if (!isPlayoffRoundId(r.id)) return false;
  if (typeof r.label !== "string" || r.label.length === 0) return false;
  if (!isSeriesBestOf(r.bestOf)) return false;
  return true;
}

export class PlayoffState {
  roundIndex: number;
  readonly rounds: readonly PlayoffRoundConfig[];
  series: SeriesState;

  constructor(args: PlayoffCampaignV1) {
    this.roundIndex = args.roundIndex;
    this.rounds = args.rounds;
    this.series = new SeriesState(args.series);
  }

  static create(args: PlayoffCreateArgs): PlayoffState {
    const rounds =
      args.rounds ?? roundsForPlayoffFormat(args.format ?? "bracket");
    const first = rounds[0];
    if (!first) {
      throw new Error("Playoff bracket requires at least one round");
    }
    const series = SeriesState.create({
      playerSide: args.playerSide,
      length: args.length,
      roleLock: args.roleLock,
      difficultyId: args.difficultyId,
      bestOf: first.bestOf,
    });
    return new PlayoffState({
      kind: "playoff",
      v: 1,
      roundIndex: 0,
      rounds,
      series: series.toCampaign(),
    });
  }

  currentRound(): PlayoffRoundConfig {
    const round = this.rounds[this.roundIndex];
    if (!round) {
      return this.rounds[this.rounds.length - 1] ?? {
        id: "pennant",
        label: "Pennant Series",
        bestOf: 3,
      };
    }
    return round;
  }

  isComplete(): boolean {
    return this.series.isComplete() && this.roundIndex >= this.rounds.length - 1;
  }

  /** Home / away that won the final series, or null if playoff still open. */
  championSide(): "home" | "away" | null {
    if (!this.isComplete()) return null;
    return this.series.winnerSide();
  }

  playerWonPlayoff(): boolean {
    return this.championSide() === this.series.playerSide;
  }

  /** Trophy noun for end card / announce — pennant vs championship. */
  trophyNoun(): string {
    if (this.rounds.length > 1) return "championship";
    return "pennant";
  }

  /**
   * Record a finished contest in the current series.
   * When the series clinches, advances to the next round (new SeriesState) or
   * marks the playoff complete on the final round.
   * Returns whether the playoff is now complete.
   */
  recordGame(result: SeriesGameResult): boolean {
    if (this.isComplete()) return true;
    const seriesDone = this.series.recordGame(result);
    if (!seriesDone) return false;
    if (this.roundIndex >= this.rounds.length - 1) return true;
    this.advanceToNextRound();
    return false;
  }

  /** Start the next bracket leg after a series clinch (not the final). */
  advanceToNextRound(): void {
    if (this.roundIndex >= this.rounds.length - 1) return;
    this.roundIndex += 1;
    const next = this.currentRound();
    this.series = SeriesState.create({
      playerSide: this.series.playerSide,
      length: this.series.length,
      roleLock: this.series.roleLock,
      difficultyId: this.series.difficultyId,
      bestOf: next.bestOf,
    });
  }

  toCampaign(): PlayoffCampaignV1 {
    return {
      kind: "playoff",
      v: 1,
      roundIndex: this.roundIndex,
      rounds: this.rounds.map((r) => ({ ...r })),
      series: this.series.toCampaign(),
    };
  }

  /** Live / SR line: "Pennant Series: Pirates 1, Phillies 0 — Game 2 of 3" */
  scoreLine(): string {
    const round = this.currentRound();
    if (this.isComplete()) {
      const winner = this.championSide() === "home" ? HOME_TEAM.shortName : AWAY_TEAM.shortName;
      const trophy = this.trophyNoun();
      return `${round.label} final: ${HOME_TEAM.shortName} ${this.series.winsHome}–${this.series.winsAway} ${AWAY_TEAM.shortName}. ${winner} take the ${trophy}.`;
    }
    const need = this.series.winsNeeded();
    const game = this.series.currentGameNumber();
    const venue = seriesVenueShort(this.series.playerSide, game);
    return `${round.label}: ${HOME_TEAM.shortName} ${this.series.winsHome}, ${AWAY_TEAM.shortName} ${this.series.winsAway}. Game ${game} of ${this.series.bestOf} ${venue} (first to ${need}).`;
  }

  /** Opening announce when the playoff begins. */
  playoffOpenLine(): string {
    const round = this.currentRound();
    const depth =
      this.rounds.length > 1
        ? ` Two rounds: ${this.rounds.map((r) => r.label).join(", then ")}.`
        : "";
    return `${round.label}. Best of ${this.series.bestOf}. First to ${this.series.winsNeeded()} wins.${depth} ${this.scoreLine()}`;
  }

  /** Spoken booth break before the next game in the same series. */
  boothBreakLine(): string {
    const next = this.series.currentGameNumber();
    const ordinal =
      next === 2
        ? "game two"
        : next === 3
          ? "game three"
          : next === 4
            ? "game four"
            : next === 5
              ? "game five"
              : `game ${next}`;
    const venue = seriesVenueSpoken(this.series.playerSide, next);
    return `We'll be right back for ${ordinal} of the ${this.currentRound().label} ${venue}. ${this.scoreLine()}`;
  }

  /** Spoken when advancing to a later round (multi-round brackets). */
  roundTransitionLine(): string {
    const round = this.currentRound();
    return `On to the ${round.label}. ${this.playoffOpenLine()}`;
  }

  /** Player-facing clinch line for the champion end card. */
  championLine(): string {
    const you = this.series.winsFor(this.series.playerSide);
    const them = this.series.winsFor(this.series.playerSide === "home" ? "away" : "home");
    const trophy = this.trophyNoun();
    if (this.playerWonPlayoff()) return `You take the ${trophy} ${you}–${them}`;
    if (this.isComplete()) return `They take the ${trophy} ${them}–${you}`;
    return this.scoreLine();
  }
}

export function isPlayoffCampaign(raw: unknown): raw is PlayoffCampaignV1 {
  if (!raw || typeof raw !== "object") return false;
  const p = raw as Partial<PlayoffCampaignV1>;
  if (p.kind !== "playoff" || p.v !== 1) return false;
  if (typeof p.roundIndex !== "number" || p.roundIndex < 0) return false;
  if (!Array.isArray(p.rounds) || p.rounds.length === 0) return false;
  if (!p.rounds.every(isPlayoffRoundConfig)) return false;
  if (p.roundIndex >= p.rounds.length) return false;
  if (!isSeriesCampaign(p.series)) return false;
  // Nested series prefs must be coherent.
  if (!isPlayerSide(String(p.series.playerSide ?? ""))) return false;
  if (!isSessionLength(p.series.length)) return false;
  if (!isRoleLock(p.series.roleLock)) return false;
  if (!isDifficultyId(String(p.series.difficultyId ?? ""))) return false;
  return true;
}

export function playoffFromCampaign(raw: unknown): PlayoffState | null {
  return isPlayoffCampaign(raw) ? new PlayoffState(raw) : null;
}

export function loadPlayoff(): PlayoffState | null {
  try {
    const raw = localStorage.getItem(PLAYOFF_STORAGE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    return playoffFromCampaign(parsed);
  } catch {
    return null;
  }
}

export function writePlayoff(playoff: PlayoffState): void {
  try {
    localStorage.setItem(PLAYOFF_STORAGE_KEY, JSON.stringify(playoff.toCampaign()));
  } catch {
    /* private browsing / quota */
  }
}

export function clearPlayoff(): void {
  try {
    localStorage.removeItem(PLAYOFF_STORAGE_KEY);
  } catch {
    /* ignore */
  }
}

/** Prefer dedicated playoff key; fall back to campaign blob on a game save. */
export function resolvePlayoffFromStorage(campaign: unknown): PlayoffState | null {
  const fromKey = loadPlayoff();
  if (fromKey) return fromKey;
  return playoffFromCampaign(campaign);
}
